/// <summary>
/// MPJ_21713_METPostProductReceiptsEntity
/// This class posts packing slips for purchase orders as per the data in METPOReceipts entity.
/// </summary>
class METPostProductReceiptService extends SysOperationServiceBase
{
    List         purchLineList = new List(Types::Record);
    str          errorMessage;
    str          infologMessage;

}

Method.Source:
    /// <summary>
    /// Executes the business logic
    /// </summary>
    /// <param name = "_contract"><c>METPostProductReceiptContract</c> class instance</param>
    private void runOperation(METPostProductReceiptContract    _contract)
    {
        int                 bundlesize, noOfPackingSlips, totalTasks, i, j, task;
        List                packingSlipList      = new List(Types::String);
        METPOReceipt        metPOReceipt, metPOReceiptLoc;

        BatchHeader batchHeader = this.getCurrentBatchHeader();

        task = 1;

        totalTasks      =   _contract.parmTasks();
        if (totalTasks <= 0)
        {
            totalTasks = 1;
        }
        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
        }

        batchHeader.parmCaption("@MET:POReceiptBatchCaption");

        while select RecId from metPOReceipt
            group by PackingSlipId
            where metPOReceipt.Processed == NoYes::Yes
                   || metPOReceipt.Error == NoYes::Yes
        {
            noOfPackingSlips++;
        }

        bundleSize      =   real2int(roundUp((noOfPackingSlips / totalTasks), 1.0));

        while select metPOReceipt
             group by PackingSlipId
               where metPOReceipt.Processed == NoYes::Yes
                   || metPOReceipt.Error == NoYes::Yes
        {
            i++;
            j++;

            packingSlipList.addEnd(metPOReceipt.PackingSlipId);

            if(i == bundlesize || j == noOfPackingSlips)
            {
                SysOperationServiceController postProductReceiptController = new SysOperationServiceController(
                                                                classStr(METPostProductReceiptService),
                                                                methodStr(METPostProductReceiptService, postProdcutReceiptSubTask));

                postProductReceiptController.parmDialogCaption(strFmt("@MET:POReceiptBatchTaskDesc", task));

                METPostProductReceiptContract postProductReceiptcontract = postProductReceiptController.getDataContractObject() as METPostProductReceiptContract;
                postProductReceiptcontract.parmReceiptList(packingSlipList);

                batchHeader.addRuntimeTask(postProductReceiptController, this.getCurrentBatchTask().RecId);
                packingSlipList = new List(Types::String);
                task++;
                i = 0;
            }
        }

        batchHeader.save();

    }

    /// <summary>
    /// Deletes purchase lines from the purchaseLineList.
    /// </summary>
    /// <param name = "_purchLineList">purchase line list.</param>
    public void clearLinesFromList(List _purchLineList)
    {
        ListIterator    listIterator = new ListIterator(_purchLineList);

        while(listIterator.more())
        {
            listIterator.delete();
        }
    }

    /// <summary>
    /// Adds purchase lines to the purchaseLineList.
    /// </summary>
    /// <param name = "_purchLine">purchase line record.</param>
    /// <returns>purchase lines list.</returns>
    public List addPOLinesToList(PurchLine _purchLine)
    {
        purchLineList.addEnd(_purchLine);

        return purchLineList; 
    }

    /// <summary>
    /// Gets the latest infolog error message
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;

        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }

    /// <summary>
    /// update the error message to metPORecipts buffer
    /// </summary>
    /// <param name = "_mbsErrorMsg">actual error message</param>
    /// <param name = "_mbsInfologMsg">infolog error message</param>
    /// <param name = "_metPOReceipts">the metPOReceipt buffer to be updated with the error message </param>
    private void updateLogLine(str _mbsErrorMsg, str _mbsInfologMsg, PackingSlipId _packingSlipId)
    {

        METPOReceipt metPOReceiptLoc;

        ttsbegin;
        while select forupdate Error, ErrorMessage
            from metPOReceiptLoc
            where metPOReceiptLoc.PackingSlipId == _packingSlipId
        {
            metPOReceiptLoc.Error = NoYes::Yes;
            metPOReceiptLoc.ErrorMessage = _mbsErrorMsg + _mbsInfologMsg;
            metPOReceiptLoc.Processed = NoYes::Yes;
            metPOReceiptLoc.ProcessedDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            metPOReceiptLoc.doUpdate();
        }
        ttscommit;
    }

    /// <summary>
    /// Performs the actual operation of posting packing slips.
    /// </summary>
    /// <param name = "_contract"><c>METPostProductReceiptContract</c> class instance.</param>
    private void postProdcutReceiptSubTask(METPostProductReceiptContract    _contract)
    {
        #OCCRetryCount

        boolean             isError;
        ListEnumerator      packingSlipListEnumerator;
        PackingSlipId       packingSlipId;
        METPOReceipt        metPOReceipt;
        PurchLine           purchLine, purchLineToSplit;
        utcdatetime         productReceiptDate;
        boolean             isPostingSuccessful;
        Qty                 purchQty, qtyToSplit;
        RecId               purchineRecId;
        packingSlipListEnumerator      = _contract.parmReceiptList().getEnumerator();

        while (packingSlipListEnumerator.moveNext())
        {
            try
            {
                ttsBegin;

                packingSlipId = packingSlipListEnumerator.current();

                while select metPOReceipt
                group by PurchaseOrderNumber, ProductReceiptDate, PackingSlipId, ProductNumber, Quantity, InventSiteId
                where metPOReceipt.Processed == NoYes::Yes
                   || metPOReceipt.Error == NoYes::Yes 
                   && metPOReceipt.PackingSlipId == packingSlipId
                {
                    productReceiptDate = metPOReceipt.ProductReceiptDate;

                    [purchineRecId, purchQty, qtyToSplit] = this.getPurchLineNew(metPOReceipt);
                    
                    select firstonly purchLine
                            where purchLine.RecId == purchineRecId;

                    if(purchLine.RecId)
                    {
                        purchLine.selectForUpdate(true);
                        purchLine.PurchReceivedNow = purchQty;
                        purchLine.modifiedField(fieldNum(PurchLine, PurchReceivedNow));
                        purchLine.update();

                        if(qtyToSplit > 0)
                        {
                            select firstonly RecId from purchLineToSplit
                                where purchLineToSplit.PurchId == metPOReceipt.PurchaseOrderNumber
                                    && purchLineToSplit.IsDeleted == NoYes::No
                                    && purchLineToSplit.ItemId == metPOReceipt.ProductNumber
                                    && purchLineToSplit.PurchQty >= qtyToSplit
                                    && purchLineToSplit.LineNumber != purchLine.LineNumber;

                            if(purchLineToSplit.RecId)
                            {
                                purchLineToSplit.selectForUpdate(true);
                                purchLineToSplit.RemainPurchPhysical = qtyToSplit;
                                purchLineToSplit.modifiedField(fieldNum(PurchLine, RemainPurchPhysical));
                                purchLineToSplit.update();
                            }
                        }
                        this.addPOLinesToList(purchLine);  //add lines to list
                    }
                    else
                    {
                        isError = true;
                    }
                }

                if(!isError)
                {
                    PurchTable      purchTable = PurchTable::find(purchLine.PurchId);
                    PurchFormLetter purchFormLetter = PurchFormLetter::construct(DocumentStatus::PackingSlip);

                    purchFormLetter.createFromLines(true);
                    purchFormLetter.parmLineList(purchLineList.pack());
                    purchFormLetter.update(purchTable, packingSlipId, DateTimeUtil::date(productReceiptDate), PurchUpdate::ReceiveNow);

                    delete_from metPOReceipt
                    where metPOReceipt.PackingSlipId == packingSlipId
                       && metPOReceipt.ProductReceiptDate == productReceiptDate;
                }

                this.clearLinesFromList(purchLineList);

                ttscommit;
            }
            catch (Exception::Error)
            {
                errorMessage    = METConstants::emptyString;
                this.getInfologMessage();
                System.Exception ex = CLRInterop::getLastException();
                if (ex != null)
                {
                    errorMessage += ex.Message + ex.ToString();
                }
                this.updateLogLine(errorMessage, infologMessage, packingSlipId);
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    errorMessage    = "@MET:POReceiptsDeadLockError";
                    this.getInfologMessage();
                    this.updateLogLine(errorMessage, infologMessage, packingSlipId);
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        errorMessage    = "@MET:POReceiptsUpdateConflictError";
                        this.getInfologMessage();
                        this.updateLogLine(errorMessage, infologMessage, packingSlipId);
                        //error (strFmt("@MET:METAMEXFreeTxtInvError", customer, company));
                        //error("@Subledger:UpdateConflictErrorThrown");
                        isError = true;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    //error (strFmt("@MET:METAMEXFreeTxtInvError", customer, company));
                    //error("@Subledger:UpdateConflictErrorThrown");
                    isError = true;
                }
            }
        }

    }

    /// <summary>
    /// Method to identify the purchase line against which the quantity will be recieved
    /// </summary>
    /// <param name = "_metPOReceipt">metPOReceipt buffer</param>
    /// <returns>purchase line that matches the criteria</returns>
    public container getPurchLineNew(METPOReceipt _metPOReceipt)
    {
        PurchLine                       purchLine, purchLineCount, purchLineToSplit;
        PurchQty                        qtyToSplit, purchqty;
        MetItemSiteSettingsSetup        itemSiteSettingsSetup;
        UnitOfMeasureSymbol             warehouseUnit, purchUnit, inventoryUnit;
        UnitOfMeasureConversionFactor   conversionFactor;
        InventDim                       inventDim;
        InventTableModule               inventTableModule;

        

        select count(RecId) from purchLineCount
            where purchLineCount.PurchId == _metPOReceipt.PurchaseOrderNumber
                    && purchLineCount.ItemId == _metPOReceipt.ProductNumber
                    && purchLineCount.PurchStatus == PurchStatus::Backorder
                    && purchLineCount.IsDeleted == NoYes::No;

        select firstonly UnitId from itemSiteSettingsSetup
                    where itemSiteSettingsSetup.ItemId == _metPOReceipt.ProductNumber
                        && itemSiteSettingsSetup.InventSiteId == _metPOReceipt.InventSiteId;

        if(purchLineCount.RecId >= 1)
        {
            select firstonly purchLine
                where purchLine.PurchId == _metPOReceipt.PurchaseOrderNumber
                    && purchLine.ItemId == _metPOReceipt.ProductNumber
                    && purchLine.PurchStatus == PurchStatus::Backorder
                    && purchLine.IsDeleted == NoYes::No
                join RecId from inventDim
                    where inventDim.inventDimId == purchLine.InventDimId
                        && inventDim.InventSiteId == _metPOReceipt.InventSiteId;

            
            warehouseUnit = itemSiteSettingsSetup.UnitId;
            purchUnit = purchLine.PurchUnit;

            select firstonly UnitId from inventTableModule
                        where inventTableModule.ItemId      == purchLine.ItemId
                           && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

            if(inventTableModule.UnitId)
            {
                inventoryUnit = inventTableModule.UnitId;
            }

            // Calculate the purchase qty from the warehouse quantity
            if(warehouseUnit == purchUnit)
            {
                purchqty = _metPOReceipt.Quantity;
            }
            else if(warehouseUnit == METConstants::emptyString)
            {
                purchqty = _metPOReceipt.Quantity;
            }
            else
            {
                conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            UnitOfMeasure::findBySymbol(purchUnit).RecId,
                            EcoResProduct::findByProductNumber(purchLine.ItemId).RecId)
                            .Factor, 0);

                if(conversionFactor != 0)
                {
                    if(purchUnit == inventoryUnit)
                    {
                        purchqty = _metPOReceipt.Quantity * conversionFactor;
                    }
                    else
                    {
                        purchqty = _metPOReceipt.Quantity / conversionFactor;
                    }
                }
                else
                {
                    conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                                UnitOfMeasure::findBySymbol(purchUnit).RecId,
                                UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                                EcoResProduct::findByProductNumber(purchLine.ItemId).RecId)
                                .Factor, 0);

                    if(conversionFactor != 0)
                    {
                        if(purchUnit == inventoryUnit)
                        {
                            purchqty = _metPOReceipt.Quantity * conversionFactor;
                        }
                        else
                        {
                            purchqty = _metPOReceipt.Quantity / conversionFactor;
                        }
                    }
                }
            }

            select forupdate firstonly purchLine
                    where purchLine.PurchId == _metPOReceipt.PurchaseOrderNumber
                        && purchLine.ItemId == _metPOReceipt.ProductNumber
                        && purchLine.PurchStatus == PurchStatus::Backorder
                        && purchLine.PurchQty >= purchqty
                        && purchLine.IsDeleted == NoYes::No
                    join RecId from inventDim
                        where inventDim.inventDimId == purchLine.InventDimId
                           && inventDim.InventSiteId == _metPOReceipt.InventSiteId
                           && inventDim.inventBatchId == _metPOReceipt.ItemBatchNumber;

            if(purchLine.RecId)
            {
                if(purchLine.PurchQty >= purchqty) //Check if quantities match
                {
                    return [purchLine.RecId, purchqty, 0];
                }
                else
                {
                    if(purchLineCount.RecId > 1)  //try to split the lines
                    {
                        qtyToSplit = purchqty - purchLine.PurchQty;

                        select firstonly RecId from purchLineToSplit
                            where purchLineToSplit.PurchId == _metPOReceipt.PurchaseOrderNumber
                                && purchLineToSplit.ItemId == _metPOReceipt.ProductNumber
                                && purchLineToSplit.PurchQty >= qtyToSplit
                                && purchLine.PurchStatus == PurchStatus::Backorder
                                && purchLineToSplit.LineNumber != purchLine.LineNumber
                                && purchLine.IsDeleted == NoYes::No;

                        if(purchLineToSplit.RecId)
                        {
                            return [purchLine.RecId, purchqty, qtyToSplit];
                        }

                    }
                    else if((purchLineCount.RecId == 1))
                    {
                        if (purchLine.OverDeliveryPct > 0) //Check if overdelivery is allowed
                        {
                            Qty maxReceivedQty = purchLine.PurchQty * (1 + purchLine.OverDeliveryPct / 100);

                            if(maxReceivedQty >= purchqty)
                            {
                                return [purchLine.RecId, purchqty, 0];
                            }
                        }
                    }
                    else
                    {
                        _metPOReceipt.Error = NoYes::Yes;
                        _metPOReceipt.ErrorMessage = strFmt("@MET:NoLinesFoundValidation", _metPOReceipt.ProductNumber, _metPOReceipt.PurchaseOrderNumber);
                    }
                }
            }
            else
            {
                _metPOReceipt.Error = NoYes::Yes;
                _metPOReceipt.ErrorMessage = strFmt("@MET:NoLinesFoundValidation", _metPOReceipt.ProductNumber, _metPOReceipt.PurchaseOrderNumber);
            }
        }
        else
        {
            _metPOReceipt.Error = NoYes::Yes;
            _metPOReceipt.ErrorMessage = strFmt("@MET:NoLinesFoundValidation", _metPOReceipt.ProductNumber, _metPOReceipt.PurchaseOrderNumber);
        }

        return [purchLine.RecId, purchqty, 0];
    }
